window.RTLBenchLSData.register("assets/d334e41d6d66b74f88ff0515c0cf58dcc2f383ab6ce7134ebd12304ab5d01bb1.txt","module origen_072932(\n    input clk,\n    input reset,\n    input switch,\n    output reg hsync,\n    output reg vsync,\n    output reg [9:0] hc,\n    output reg [9:0] vc,\n    output reg disp_on\n);\n\n    parameter hpixels = 800;\n    parameter vlines = 521;\n\n    reg vsenable;\n\n    always @(posedge clk or posedge reset) begin\n        if (reset) begin\n            hc <= 10'd0;\n            vsenable <= 1'b0;\n        end else if (switch) begin\n            if (hc == hpixels - 1) begin\n                hc <= 10'd0;\n                vsenable <= 1'b1;\n            end else begin\n                hc <= hc + 1'b1;\n                vsenable <= 1'b0;\n            end\n        end\n    end\n\n    always @(posedge clk or posedge reset) begin\n        if (reset) begin\n            vc <= 10'd0;\n        end else if (switch && vsenable) begin\n            if (vc == vlines - 1) begin\n                vc <= 10'd0;\n            end else begin\n                vc <= vc + 1'b1;\n            end\n        end\n    end\n\n    always @(posedge clk or posedge reset) begin\n        if (reset) begin\n            hsync <= 1'b1;\n            vsync <= 1'b1;\n            disp_on <= 1'b0;\n        end else if (switch) begin\n            hsync <= (hc < 10'd8) || (hc > 10'd103);\n            vsync <= (vc < 10'd2) || (vc > 10'd3);\n            disp_on <= (hc >= 10'd152) && (hc < 10'd791) && (vc >= 10'd37) && (vc < 10'd516);\n        end\n    end\n\nendmodule");
